export const FONT_FACE_CSS = "/* THE BRAND FACES, SELF-HOSTED, AND THE ONLY WAY THEY LOAD (his instruction of 22 Sep 2026: no Google\n   Fonts). The files are Google's own latin subsets, fetched once and kept in src/fonts/ beside this\n   file with their OFL licences; nothing here loads off another origin. A page that LINKS this file\n   resolves fonts/ against it; a page that INLINES these rules (the desk, the Counter, QR Command)\n   serves fonts/ beside itself. Both are variable fonts and the weight ranges below are the files'\n   own, so a 700 resolves to the face and is never synthesised. Symbols outside the latin range (a\n   tick, a triangle) fall to the system face, as they always did. */\n@font-face {\n  font-family: 'Fraunces';\n  font-style: normal;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(/fonts/fraunces-latin.woff2) format('woff2');\n  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;\n}\n@font-face {\n  font-family: 'JetBrains Mono';\n  font-style: normal;\n  font-weight: 400 800;\n  font-display: swap;\n  src: url(/fonts/jetbrains-mono-latin.woff2) format('woff2');\n  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;\n}\n";
